const priceForm=root.querySelector('.diesel-price-form'),priceMessage=root.querySelector('.diesel-price-message');
priceForm.elements.date.value=new Date().toLocaleDateString('en-CA');
function dieselPriceNumber(v){const x=String(v??'').replace(/R\$|\s/g,'');return Number(x.includes(',')?x.replace(/\./g,'').replace(',','.'):x)}
function dieselMoney(v){return Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL',minimumFractionDigits:3,maximumFractionDigits:3})}
function latestDieselPrice(company){return [...dieselPrices].filter(p=>p.company==='Todas'||p.company===company).sort((a,b)=>b.date.localeCompare(a.date)||(b.createdAt||'').localeCompare(a.createdAt||''))[0]}
function fillLatestDieselPrice(){const p=latestDieselPrice(form.elements.company.value);if(p&&!form.dataset.id)form.elements.price.value=Number(p.price).toFixed(3).replace('.',',')}
form.elements.company.addEventListener('change',()=>{if(!form.dataset.id)fillLatestDieselPrice()});form.elements.price.addEventListener('blur',()=>{const n=dieselPriceNumber(form.elements.price.value);if(form.elements.price.value.trim()&&Number.isFinite(n))form.elements.price.value=n.toFixed(3).replace('.',',')});priceForm.elements.price.addEventListener('blur',()=>{const n=dieselPriceNumber(priceForm.elements.price.value);if(priceForm.elements.price.value.trim()&&Number.isFinite(n))priceForm.elements.price.value=n.toFixed(3).replace('.',',')});
function renderDieselPrices(){
const sorted=[...dieselPrices].sort((a,b)=>a.date.localeCompare(b.date)||(a.createdAt||'').localeCompare(b.createdAt||'')),latest=sorted.at(-1),previous=sorted.at(-2),diff=latest&&previous?latest.price-previous.price:null,pct=diff!==null&&previous.price?diff/previous.price*100:null;
root.querySelector('.diesel-price-kpis').innerHTML='<div><small>Último valor</small><strong>'+(latest?dieselMoney(latest.price):'—')+'</strong></div><div><small>Variação em reais</small><strong>'+(diff===null?'—':(diff>0?'+':'')+dieselMoney(diff))+'</strong></div><div><small>Variação percentual</small><strong>'+(pct===null?'—':(pct>0?'+':'')+pct.toFixed(2).replace('.',',')+'%')+'</strong></div>';
const chart=root.querySelector('.diesel-price-chart');
if(!sorted.length){chart.innerHTML='<p>Cadastre o primeiro valor para visualizar o gráfico.</p>';root.querySelector('.diesel-price-history').innerHTML='';return}
const w=800,h=240,pad=48,values=sorted.map(p=>Number(p.price)),min=Math.min(...values),max=Math.max(...values),range=Math.max(max-min,.1),lo=min-range*.15,hi=max+range*.15;
const points=sorted.map((p,i)=>({x:pad+(w-pad*2)*(sorted.length===1?.5:i/(sorted.length-1)),y:h-pad-(p.price-lo)/(hi-lo)*(h-pad*2),p}));
chart.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Evolução dos preços do diesel" style="display:block;width:100%;height:auto;max-height:310px"><line x1="'+pad+'" y1="'+(h-pad)+'" x2="'+(w-pad)+'" y2="'+(h-pad)+'" stroke="#7188a5"/><line x1="'+pad+'" y1="'+pad+'" x2="'+pad+'" y2="'+(h-pad)+'" stroke="#7188a5"/><text x="4" y="'+(pad+5)+'" fill="#d3e3f7" font-size="12">'+dieselMoney(max)+'</text><text x="4" y="'+(h-pad-5)+'" fill="#d3e3f7" font-size="12">'+dieselMoney(min)+'</text><polyline points="'+points.map(p=>p.x.toFixed(1)+','+p.y.toFixed(1)).join(' ')+'" fill="none" stroke="#4db3ff" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>'+points.map(p=>'<circle cx="'+p.x+'" cy="'+p.y+'" r="4" fill="#7de4ff"><title>'+day(p.p.date)+' · '+p.p.company+' · '+dieselMoney(p.p.price)+'</title></circle>').join('')+'</svg><small>Gráfico por data de atualização. Toque nos pontos para consultar valores.</small>';
root.querySelector('.diesel-price-history').innerHTML='<h4>Histórico de atualizações</h4><div class="table-scroll"><table><thead><tr><th>Data</th><th>Empresa</th><th>Preço por litro</th><th>Variação</th></tr></thead><tbody>'+sorted.slice().reverse().map((p,i)=>{const older=sorted[sorted.length-2-i],delta=older?p.price-older.price:null;return '<tr><td>'+day(p.date)+'</td><td>'+esc(p.company)+'</td><td>'+dieselMoney(p.price)+'</td><td>'+(delta===null?'—':(delta>0?'+':'')+dieselMoney(delta))+'</td></tr>'}).join('')+'</tbody></table></div>';
}
async function loadDieselPrices(){const r=await fetch('/api/diesel-prices');if(!r.ok)throw Error('Não foi possível carregar os preços.');dieselPrices=(await r.json()).prices||[];renderDieselPrices();fillLatestDieselPrice()}
priceForm.onsubmit=async e=>{e.preventDefault();const price=dieselPriceNumber(priceForm.elements.price.value),date=priceForm.elements.date.value,company=priceForm.elements.company.value;if(!Number.isFinite(price)||price<=0){priceMessage.textContent='Informe um preço válido.';return}const btn=priceForm.querySelector('button[type="submit"]');btn.disabled=true;try{const r=await fetch('/api/diesel-prices',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({price,date,company})});const j=await r.json();if(!r.ok)throw Error(j.error||'Falha ao salvar');dieselPrices=j.prices;renderDieselPrices();fillLatestDieselPrice();priceForm.elements.price.value='';priceMessage.textContent='Valor registrado no banco de dados.'}catch(error){priceMessage.textContent=error.message}finally{btn.disabled=false}};
loadDieselPrices().catch(e=>priceMessage.textContent=e.message);
